// pyrepr.mjs — Python-compatible repr()/print() formatting helpers.
//
// Reimplements the subset of CPython's object repr semantics needed to make
// console.log output byte-identical with Python's print(): string repr with
// quote selection and escaping, list repr, dict-style repr, and a dispatch
// helper used by the entry script.

// Code points Python's str.isprintable() reports as non-printable for the
// ranges we can encounter (categories Cc, Cf, Cs, Co, Zl, Zp, Zs minus the
// ASCII space). U+00A0 .. U+00FF handled individually below.
const NON_PRINTABLE_RANGES = [
  [0x0000, 0x001f], // C0 controls
  [0x007f, 0x00a0], // DEL, C1 controls, NBSP (Zs)
  [0x00ad, 0x00ad], // soft hyphen (Cf)
  [0x0600, 0x0605], [0x061c, 0x061c], [0x06dd, 0x06dd], [0x070f, 0x070f],
  [0x0890, 0x0891], [0x08e2, 0x08e2],
  [0x1680, 0x1680], // ogham space mark (Zs)
  [0x180e, 0x180e], // mongolian vowel separator (Cf)
  [0x2000, 0x200f], // en quad .. zero-width joiner (Zs/Cf)
  [0x2028, 0x202e], // line/para separators (Zl/Zp) + bidi controls (Cf)
  [0x205f, 0x2064], // math space (Zs) + invisible operators (Cf)
  [0x2066, 0x206f], // bidi isolates + deprecated formatting (Cf)
  [0x3000, 0x3000], // ideographic space (Zs)
  [0xd800, 0xdfff], // surrogates (Cs)
  [0xe000, 0xf8ff], // private use (Co)
  [0xfeff, 0xfeff], // BOM / zero-width no-break space (Cf)
  [0xfff9, 0xfffb], // interlinear annotation (Cf)
  [0x110bd, 0x110bd], [0x110cd, 0x110cd],
  [0x13430, 0x1343f],
  [0x1bca0, 0x1bca3], [0x1d173, 0x1d17a],
  [0xe0000, 0xe0fff], // tags + variation selectors supplement (Cf)
  [0xf0000, 0xffffd], [0x100000, 0x10fffd], // plane 15/16 private use (Co)
];

export function isPrintable(cp) {
  if (cp === 0x20) return true; // ASCII space is printable
  for (const [lo, hi] of NON_PRINTABLE_RANGES) {
    if (cp < lo) return true;
    if (cp <= hi) return false;
  }
  return true;
}

function escapeCodePoint(cp) {
  if (cp <= 0xff) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp <= 0xffff) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

// Mirrors CPython's unicode_repr(): single quotes by default; double quotes
// only when the string contains a single quote and no double quote.
export function reprStr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\' || ch === quote) {
      out += '\\' + ch;
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (!isPrintable(cp)) {
      out += escapeCodePoint(cp);
    } else {
      out += ch;
    }
  }
  return out + quote;
}

// Dispatch repr: strings, numbers (int-valued), arrays (Python list),
// FrozenDict-like objects exposing __pyRepr__().
export function pyRepr(value) {
  if (typeof value === 'string') return reprStr(value);
  if (typeof value === 'number') return String(value);
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (value === null || value === undefined) return 'None';
  if (Array.isArray(value)) return '[' + value.map(pyRepr).join(', ') + ']';
  if (typeof value.__pyRepr__ === 'function') return value.__pyRepr__();
  return String(value);
}

// Python len() counts Unicode code points, not UTF-16 units.
export function pyLen(s) {
  return typeof s === 'string' ? Array.from(s).length : s.length;
}

// strutils.mjs — reimplementation of the boltons.strutils functions used by
// the source script: camel2under, under2camel, slugify, unit_len,
// cardinalize (plus the pluralize helper they rely on).

// Equivalent of boltons' _camel2under_re:
//   ((?<=[a-z0-9])[A-Z]|(?!^)[A-Z](?=[a-z]))
// An uppercase letter is preceded by an underscore when it directly follows
// a lowercase letter/digit, or when it starts a new capitalized word in the
// middle of the string (e.g. "HTTPServer" -> "HTTP_Server").
const CAMEL2UNDER_RE = /((?<=[a-z0-9])[A-Z]|(?!^)[A-Z](?=[a-z]))/g;

export function camel2under(camelString) {
  return camelString.replace(CAMEL2UNDER_RE, '_$1').toLowerCase();
}

// Python's str.capitalize() titlecases the first character and lowercases
// the rest. JS has no titlecase, so map the characters whose Unicode
// titlecase differs from their uppercase.
const TITLECASE_EXCEPTIONS = new Map([
  ['ß', 'Ss'],
  ['ǆ', 'ǅ'], ['ǉ', 'ǈ'], ['ǌ', 'ǋ'], ['ǳ', 'ǲ'],
  ['ŉ', 'ʼN'],
  ['ﬀ', 'Ff'], ['ﬁ', 'Fi'], ['ﬂ', 'Fl'],
  ['ﬃ', 'Ffi'], ['ﬄ', 'Ffl'], ['ﬅ', 'St'], ['ﬆ', 'St'],
]);

function pyCapitalize(word) {
  if (!word) return word;
  const chars = Array.from(word); // iterate by code point
  const first = chars[0];
  const rest = chars.slice(1).join('').toLowerCase();
  const titled = TITLECASE_EXCEPTIONS.has(first)
    ? TITLECASE_EXCEPTIONS.get(first)
    : first.toUpperCase();
  return titled + rest;
}

// boltons: ''.join(w.capitalize() or '_' for w in under_string.split('_'))
export function under2camel(underString) {
  return underString
    .split('_')
    .map((w) => pyCapitalize(w) || '_')
    .join('');
}

// Delimiter character class verified black-box against the reference
// implementation: tab, space, and every ASCII punctuation character except
// the backslash. Non-ASCII characters are always preserved.
const SLUG_PUNCT_RE = /[\t !"#$%&'()*+,\-./:;<=>?@[\]^_`{|}~]+/;

// boltons.slugify(text, delim='_', lower=True, ascii=False)
export function slugify(text, delim = '_', lower = true, ascii = false) {
  let t = text;
  if (ascii) {
    // Drop non-ASCII bytes like Python's text.encode('ascii', 'ignore').
    t = t.replace(/[^\x00-\x7f]/g, '');
  }
  if (lower) {
    t = t.toLowerCase();
  }
  // Python strips whitespace from both ends before splitting; the empty
  // fragments produced by leading/trailing delimiters are dropped anyway.
  const words = t.trim().split(SLUG_PUNCT_RE).filter((w) => w !== '');
  return words.join(delim);
}

export function pluralize(word) {
  if (!word) return word;
  const lower = word.toLowerCase();
  if (/(?:s|x|z|ch|sh)$/.test(lower)) return word + 'es';
  if (/[^aeiou]y$/.test(lower)) return word.slice(0, -1) + 'ies';
  return word + 's';
}

// boltons: returns unit_noun unchanged for count == 1, pluralized otherwise.
export function cardinalize(unitNoun, count) {
  if (count === 1) return unitNoun;
  return pluralize(unitNoun);
}

// boltons: "<count> <unit_noun>", pluralizing the noun unless count == 1.
export function unit_len(sizedIterable, unitNoun = 'item') {
  const count = sizedIterable.length;
  return `${count} ${cardinalize(unitNoun, count)}`;
}

// dictutils.mjs — reimplementation of boltons.dictutils.FrozenDict for the
// behavior exercised by the source script: construction from a mapping/
// entries and Python-faithful repr output.

import { pyRepr } from './pyrepr.mjs';

// An immutable, insertion-ordered string-keyed mapping. Setting an existing
// key replaces its value while keeping its original position, matching
// Python dict semantics.
export class FrozenDict {
  constructor(entries = []) {
    const pairs = entries instanceof Map ? entries.entries() : entries;
    this._map = new Map(pairs);
    Object.freeze(this);
  }

  get size() {
    return this._map.size;
  }

  has(key) {
    return this._map.has(key);
  }

  get(key, fallback = undefined) {
    return this._map.has(key) ? this._map.get(key) : fallback;
  }

  keys() {
    return this._map.keys();
  }

  values() {
    return this._map.values();
  }

  entries() {
    return this._map.entries();
  }

  [Symbol.iterator]() {
    return this._map[Symbol.iterator]();
  }

  // FrozenDict repr: FrozenDict({'k': 'v', 'k2': 2})
  __pyRepr__() {
    const items = [];
    for (const [k, v] of this._map) {
      items.push(`${pyRepr(k)}: ${pyRepr(v)}`);
    }
    return `FrozenDict({${items.join(', ')}})`;
  }

  toString() {
    return this.__pyRepr__();
  }
}

// argparse.mjs — minimal reimplementation of the Python argparse behavior
// used by the source script: one required option `--a` (plus the implicit
// -h/--help), with argparse-compatible usage/error output and exit codes.

import { basename } from 'node:path';

const LONG_OPTIONS = ['--help', '--a'];

// argparse's _negative_number_matcher; since no defined option looks like a
// negative number, such tokens are treated as values, not options.
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

function isOptionLike(token) {
  return (
    token.length > 1 && token.startsWith('-') && !NEGATIVE_NUMBER_RE.test(token)
  );
}

export function makeParser(progName) {
  const prog = progName ?? basename(process.argv[1] ?? 'test17.mjs');
  const usage = `usage: ${prog} [-h] --a A`;
  const help = `${usage}

options:
  -h, --help  show this help message and exit
  --a A       Comma-separated strings`;

  function exitWithError(message) {
    process.stderr.write(`${usage}\n${prog}: error: ${message}\n`);
    process.exit(2);
  }

  function printHelpAndExit() {
    process.stdout.write(help + '\n');
    process.exit(0);
  }

  function parse(argv) {
    let aValue;
    const extras = [];
    let positionalOnly = false;
    let i = 0;

    while (i < argv.length) {
      const arg = argv[i];

      if (positionalOnly || !isOptionLike(arg)) {
        extras.push(arg);
        i += 1;
        continue;
      }
      if (arg === '--') {
        positionalOnly = true;
        i += 1;
        continue;
      }

      let optName = arg;
      let explicitValue;
      if (arg.startsWith('--')) {
        const eq = arg.indexOf('=');
        if (eq !== -1) {
          optName = arg.slice(0, eq);
          explicitValue = arg.slice(eq + 1);
        }
        // argparse allow_abbrev=True: unambiguous prefixes of long options.
        if (!LONG_OPTIONS.includes(optName)) {
          const matches = LONG_OPTIONS.filter((o) => o.startsWith(optName));
          if (matches.length === 1) {
            optName = matches[0];
          } else if (matches.length > 1) {
            exitWithError(
              `ambiguous option: ${optName} could match ${matches.join(', ')}`
            );
          } else {
            extras.push(arg);
            i += 1;
            continue;
          }
        }
      }

      if (optName === '-h' || optName === '--help') {
        printHelpAndExit();
      }
      if (optName === '--a') {
        if (explicitValue !== undefined) {
          aValue = explicitValue;
          i += 1;
          continue;
        }
        const next = argv[i + 1];
        if (next === undefined || isOptionLike(next)) {
          exitWithError('argument --a: expected one argument');
        }
        aValue = next;
        i += 2;
        continue;
      }

      extras.push(arg);
      i += 1;
    }

    // argparse checks required arguments before reporting unrecognized ones.
    if (aValue === undefined) {
      exitWithError('the following arguments are required: --a');
    }
    if (extras.length > 0) {
      exitWithError(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return { a: aValue };
  }

  return { parse, prog, usage, help };
}

export function parseArgs(argv, progName) {
  return makeParser(progName).parse(argv);
}

